test('valid Claim temporal survives planning and publication metadata stays separate', async () => { const temporal = { asOf: '2026-08-05', scope: { type: 'period' as const, start: '2026-01-01', end: '2026-12-31', label: '2026E' } }; const groups = [group(entity('e', 'Alpha')), group(claim('c', 'Alpha has the stated outlook', 'e', { temporal }))]; const resolution = await resolve(groups); const input = plannerInput(groups, resolution.result); const planned = planKnowledgeChangeSet({ ...input, rawManifest: { ...input.rawManifest, suppliedMetadata: { ...input.rawManifest.suppliedMetadata, publishedAt: '2026-08-05' } } }); const operation = planned.changeSet?.knowledgeOperations.find((item) => item.type === 'create' && item.object.id.startsWith('claim:')); assert.equal(operation?.type, 'create'); if (operation?.type === 'create') assert.deepEqual((operation.object as { temporal?: unknown }).temporal, temporal); const source = planned.changeSet?.sourceOperations[0]; assert.equal(source?.type, 'source_create'); if (source?.type === 'source_create') assert.equal(source.source.publishedAt, '2026-08-05'); const noTemporalGroups = [group(entity('e', 'Beta')), group(claim('c', 'Beta has the stated outlook', 'e'))]; const noTemporalResolution = await resolve(noTemporalGroups); const noTemporalPlan = planKnowledgeChangeSet({ ...plannerInput(noTemporalGroups, noTemporalResolution.result), rawManifest: { ...input.rawManifest, suppliedMetadata: { ...input.rawManifest.suppliedMetadata, publishedAt: '2026-08-05' } } }); const noTemporalClaim = noTemporalPlan.changeSet?.knowledgeOperations.find((item) => item.type === 'create' && item.object.id.startsWith('claim:')); assert.equal(noTemporalClaim?.type, 'create'); if (noTemporalClaim?.type === 'create') assert.equal('temporal' in noTemporalClaim.object, false) })
test('accepted Candidate temporal variants remain accepted by canonical ChangeSet validation', async () => { const variants = [undefined, null, { asOf: '2026-08-05', scope: { type: 'period', start: '2026-01-01', end: '2026-12-31', label: '2026E' } }] as const; const extractionUnit = { proposedUnitId: 'unit-1', topic: 'test', semanticPurpose: 'test', primaryRefs: [{ kind: 'block' as const, blockId: 'block-1' }], contextRefs: [] }; for (const temporal of variants) { const rawClaim = { candidateId: 'claim-1', claimType: 'fact', statement: 'Alpha has the stated outlook.', subjectRefs: [{ candidateRef: 'alpha', mention: 'Alpha' }], evidenceBlockRefs: ['block-1'], reason: 'direct statement', ...(temporal === undefined ? {} : { temporal }) }; const extracted = validateExtractKnowledge({ entities: [{ candidateId: 'alpha', entityType: 'company', name: 'Alpha', evidenceBlockRefs: ['block-1'], reason: 'named' }], relations: [], claims: [rawClaim] }, { document, reportMap, unit: extractionUnit, schemaContext: buildCurationSchemaContext('knowledge_extraction') }); assert.equal(extracted.claims.length, 1); assert.equal(extracted.rejected.length, 0); const groups = [group(extracted.entities[0]!), group(extracted.claims[0]!)]; const resolution = await resolve(groups); const planned = planKnowledgeChangeSet(plannerInput(groups, resolution.result)); assert.equal(planned.changeSet !== undefined, true); const root = await createKnowledgeBase(); try { const handle = await new KnowledgeBaseRegistry().mount(root); const validation = await validateKnowledgeChangeSetV03(handle, planned.changeSet!, { mode: 'dry_run', virtualRawRefs: [rawRef] }); assert.equal(validation.report.status, 'passed', JSON.stringify(validation.report.errors)); } finally { await removeKnowledgeBase(root) } } })
test('Planner isolates a bypassed malformed Claim temporal and preserves safe ChangeSet operations', async () => { const malformed = claim('bad', 'Alpha has a malformed temporal', 'e', { temporal: { asOf: '2026E', scope: { type: 'period', start: null, end: null, label: null } } }); const safe = claim('safe', 'Alpha has a safe temporal', 'e', { temporal: { asOf: null, scope: { type: 'period', start: null, end: null, label: '2026E' }, }, evidenceBlockRefs: ['block-1'] }); const groups = [group(entity('e', 'Alpha')), group(safe), group(malformed as unknown as ClaimCandidate)]; const resolution = await resolve(groups); const planned = planKnowledgeChangeSet(plannerInput(groups, resolution.result)); const operations = planned.changeSet?.knowledgeOperations ?? []; assert.equal(operations.filter((item) => item.type === 'create' && item.object.id.startsWith('claim:')).length, 1); assert.equal(operations.some((item) => item.type === 'create' && item.object.id.includes('bad')), false); const review = planned.reviewItems.find((item) => item.candidateId === 'bad'); assert.equal(review?.origin, 'planner'); assert.match(review?.rationale ?? '', /Claim temporal is not Schema 0\.3 admissible/); assert.equal(planned.changeSet !== undefined, true); const root = await createKnowledgeBase(); try { const handle = await new KnowledgeBaseRegistry().mount(root); const validation = await validateKnowledgeChangeSetV03(handle, planned.changeSet!, { mode: 'dry_run', virtualRawRefs: [rawRef] }); assert.equal(validation.report.status, 'passed', JSON.stringify(validation.report.errors)); } finally { await removeKnowledgeBase(root) } })
