test('semantic cases project bounded real document evidence only', async () => { const caseDocument = { ...document, normalizedText: 'FULL NORMALIZED TEXT MUST NOT LEAK', blocks: [{ ...document.blocks[0]!, text: 'SK海力士预计2026年HBM收入增长...', page: 3 }, { blockId: 'unrelated', type: 'paragraph' as const, text: 'UNRELATED BLOCK MUST NOT LEAK', sectionRef: null, page: 4, locator: { page: 4 }, order: 2 }] }; const casePlan = { units: [{ unitId: 'unit-1', proposedUnitId: 'unit-1', topic: 'test', semanticPurpose: 'test', primaryRefs: [], contextRefs: [], primaryBlockIds: ['block-1'], contextBlockIds: ['unrelated'] }], excludedBlockIds: [], estimatedContextTokens: {} }; const { mock } = await resolve([group(entity('e', 'Alpha', 'company', { evidenceBlockRefs: ['block-1'] }))], assets([{ id: 'entity:alpha', type: 'company', name: 'Alpha', lifecycle: { status: 'active' } }]), { outcome: 'equivalent_to', targetAlias: 'existing-001', rationale: 'Same bounded evidence.' }, { document: caseDocument, plan: casePlan }); const request = mock.calls.find((item) => item.operation === 'resolveSemanticCase'); const input = request?.input as { resolutionCase: { evidence: readonly { blockId: string; blockType: string; sectionRef: string | null; page: number | null; role: string; textExcerpt: string }[] } }; assert.deepEqual(input.resolutionCase.evidence, [{ blockId: 'block-1', blockType: 'paragraph', sectionRef: null, page: 3, role: 'primary', textExcerpt: 'SK海力士预计2026年HBM收入增长...' }]); const serialized = JSON.stringify(request?.input); assert.equal(serialized.includes('UNRELATED BLOCK MUST NOT LEAK'), false); assert.equal(serialized.includes('FULL NORMALIZED TEXT MUST NOT LEAK'), false); assert.equal(serialized.includes('reportMap'), false); assert.equal(serialized.includes('entity:alpha'), false) })
