test('semantic case count is separate from retry call count', async () => { let alphaAttempts = 0; const response = (request: { input: unknown }) => { const name = ((request.input as { resolutionCase: { candidateProjection: { name?: string } } }).resolutionCase.candidateProjection.name); if (name === 'Alpha') { alphaAttempts += 1; if (alphaAttempts === 1) return { outcome: 'unsupported', rationale: 'Retry this case.' } } return { outcome: 'equivalent_to', targetAlias: 'existing-001', rationale: 'Bounded retry success.' } }; const groups = [group(entity('a', 'Alpha')), group(entity('b', 'Beta'))]; const { result } = await resolve(groups, assets([{ id: 'entity:alpha', type: 'company', name: 'Alpha', lifecycle: { status: 'active' } }, { id: 'entity:beta', type: 'company', name: 'Beta', lifecycle: { status: 'active' } }]), response, { maxResolutionCases: 2, maxResolutionAttempts: 2 }); assert.equal(result.semanticCaseCount, 2); assert.equal(result.semanticCaseCalls, 3); assert.equal(result.summary.semanticCases, 2); assert.equal(result.summary.semanticCaseCalls, 3) })
test('mixed fresh Knowledge Resolution graph plans all canonical references', async () => { const entityGroups = Array.from({ length: 60 }, (_, index) => group(entity(`e-${index}`, `Fresh ${index}`, index < 15 ? 'company' : index < 30 ? 'product' : index < 45 ? 'industry' : 'technology'))); const relationGroups = Array.from({ length: 15 }, (_, index) => group(relation(`offers-${index}`, 'offers_product', `e-${index}`, `e-${15 + index}`))).concat(Array.from({ length: 15 }, (_, index) => group(relation(`develops-${index}`, 'develops_technology', `e-${index}`, `e-${45 + index}`)))); const claimGroups = Array.from({ length: 30 }, (_, index) => group(claim(`claim-${index}`, `Fresh ${index} is documented`, `e-${index}`, { evidenceBlockRefs: ['block-1'] }))); const groups = [...entityGroups, ...relationGroups, ...claimGroups]; const mixedPlan = { ...plan, units: [{ unitId: 'unit-1', proposedUnitId: 'unit-1', topic: 'mixed', semanticPurpose: 'mixed', primaryRefs: [], contextRefs: [], primaryBlockIds: ['block-1'], contextBlockIds: [] }] }; const resolution = await resolve(groups, emptyAssets(), undefined, { plan: mixedPlan }); const planned = planKnowledgeChangeSet({ ...plannerInput(groups, resolution.result), plan: mixedPlan }); const operations = planned.changeSet?.knowledgeOperations ?? []; assert.equal(resolution.result.semanticCaseCount, 0); assert.equal(resolution.result.semanticCaseCalls, 0); assert.equal(planned.reviewItems.length, 0); assert.equal(operations.filter((item) => item.type === 'create' && 'object' in item && item.object.id.startsWith('entity:')).length, 60); assert.equal(operations.filter((item) => item.type === 'create' && 'object' in item && item.object.id.startsWith('relation:')).length, 30); assert.equal(operations.filter((item) => item.type === 'create' && 'object' in item && item.object.id.startsWith('claim:')).length, 30); assert.equal(planned.changeSet?.sourceOperations.length, 1); assert.equal(JSON.stringify(planned.changeSet).includes('planned-entity-'), false); assert.equal(planned.changeSet !== undefined, true) })
test('Schema-valid Relation state change becomes replace_state and invalid nested state is isolated', async () => { const baseEntities = [{ id: 'entity:company', type: 'company', name: 'Company', exchange: 'NYSE', ticker: 'COMP', lifecycle: { status: 'active' } }, { id: 'entity:industry', type: 'industry', name: 'Industry', lifecycle: { status: 'active' } }]; const old = { id: 'relation:old', type: 'business_exposure', sourceRef: 'entity:company', targetRef: 'entity:industry', attributes: { exposureBasis: 'unknown', realizationStage: 'unknown', materiality: 'minor' }, sourceRefs: ['source:old'], lifecycle: { status: 'active' } }; const response = (request: { input: unknown }) => ((request.input as { resolutionCase: { caseKind: string } }).resolutionCase.caseKind === 'EntityBindingCase' ? { outcome: 'equivalent_to', targetAlias: 'existing-001', rationale: 'Same endpoint.' } : { outcome: 'state_changed', targetAlias: 'existing-001', rationale: 'The exposure state changed.' }); const validGroups = [group(entity('c', 'Company', 'company', { semanticFields: { exchange: 'NYSE', ticker: 'COMP' } })), group(entity('i', 'Industry', 'industry')), group(relation('r', 'business_exposure', 'c', 'i', { exposureBasis: 'direct_operation', realizationStage: 'commercialized', materiality: 'core' }))]; const valid = await resolve(validGroups, assets(baseEntities, [old]), response); const validPlan = planKnowledgeChangeSet(plannerInput(validGroups, valid.result, assets(baseEntities, [old]))); const update = validPlan.changeSet?.knowledgeOperations.find((item) => item.type === 'update'); assert.equal(valid.result.intents.find((item) => item.candidateRef === 'r')?.disposition, 'replace_state'); assert.equal(update?.type, 'update'); if (update?.type === 'update') assert.equal((update.object as { attributes?: { materiality?: string } }).attributes?.materiality, 'core'); const invalidGroups = [group(entity('c', 'Company', 'company', { semanticFields: { exchange: 'NYSE', ticker: 'COMP' } })), group(entity('i', 'Industry', 'industry')), group(relation('r', 'business_exposure', 'c', 'i', { financialContribution: { revenueShare: 2 } }))]; const invalid = await resolve(invalidGroups, assets(baseEntities, [old]), response); const invalidPlan = planKnowledgeChangeSet(plannerInput(invalidGroups, invalid.result, assets(baseEntities, [old]))); assert.equal(invalidPlan.changeSet?.knowledgeOperations.some((item) => item.type === 'update' && item.knowledgeId === 'relation:old') ?? false, false); assert.ok(invalidPlan.reviewItems.some((item) => item.candidateId === 'r')) })

const themeDocument = { ...document, sections: [{ sectionId: 'section-1', title: 'Theme', level: 1, parentSectionId: null, blockRefs: ['block-1', 'block-2', 'block-3', 'block-4', 'block-5', 'block-6', 'block-7', 'block-8'] }], blocks: Array.from({ length: 8 }, (_, index) => ({ blockId: `block-${index + 1}`, type: 'paragraph' as const, text: `Material theme evidence ${index + 1}`, sectionRef: 'section-1', page: 1, locator: { page: 1 }, order: index + 1 })) }
const themePlan: AcceptedExtractionPlan = { units: [{ unitId: 'unit-1', proposedUnitId: 'unit-1', topic: 'theme', semanticPurpose: 'theme', primaryRefs: [], contextRefs: [], primaryBlockIds: ['block-1'], contextBlockIds: [] }], excludedBlockIds: [], estimatedContextTokens: {} }
function investmentTheme(id: string, name: string, extra: Record<string, unknown> = {}): EntityCandidate { return entity(id, name, 'investment_theme', { evidenceBlockRefs: ['block-1'], ...extra }) }
function themeAsset(id: string, name: string, extra: Record<string, unknown> = {}): Record<string, unknown> { return { id, type: 'investment_theme', name, themeGroupRef: 'theme-group:default', lifecycle: { status: 'active' }, ...extra } }
function themeExistingAssets(values: Record<string, unknown>[]): KnowledgeAssetCollectionV03 { return assets(values) }
async function resolveTheme(candidate: EntityCandidate, existing: KnowledgeAssetCollectionV03 = emptyAssets(), response?: unknown, options: Record<string, unknown> = {}) { const mock = executor(response); const skill = new KnowledgeCurationSkill({ executor: mock }); const result = await resolveKnowledge({ assets: existing, document: themeDocument as never, groups: [group(candidate)], reportMap, plan: themePlan, rawRef, skill, ...options } as never); return { result, mock } }

test('InvestmentTheme same name uses bounded coverage case and no durable ID is exposed', async () => { const { result, mock } = await resolveTheme(investmentTheme('theme', 'AI Compute'), themeExistingAssets([themeAsset('entity:ai-compute', 'AI Compute', { definition: 'AI infrastructure cycle', inclusionCriteria: ['compute demand'], exclusionCriteria: ['unrelated software'] })]), { outcome: 'matches_existing', targetAlias: 'existing-theme-001', rationale: 'The existing theme covers the candidate.' }); assert.equal(result.bindings.get('theme')?.state, 'BoundExisting'); assert.equal(result.bindings.get('theme')?.ref, 'entity:ai-compute'); const request = mock.calls.find((item) => ((item.input as { resolutionCase?: { caseKind?: string } }).resolutionCase?.caseKind) === 'InvestmentThemeCoverageCase'); assert.ok(request); const serialized = JSON.stringify(request?.input); assert.doesNotMatch(serialized, /entity:ai-compute|theme-group:default/); assert.match(serialized, /AI infrastructure cycle/); assert.match(request?.instruction ?? '', /only when no supplied existing InvestmentTheme reasonably covers the Candidate may you return potential_new/i); assert.equal(result.potentialNewInvestmentThemes.length, 0) })

