test('ReviewSummary counts all events while bounding category samples', () => { const items = Array.from({ length: 8 }, (_, index) => ({ candidateId: `e-${index}`, kind: 'entity', rationale: `Independent review ${index}`, dependentCandidateIds: [], stage: 'planner', category: 'other' as const, origin: 'planner' as const, dependency: false, reviewKey: `planner|e-${index}` })); const summary = normalizeReviewSummary({ plannerReviewItems: items, candidateGroups: items.map((item) => group(entity(item.candidateId, item.candidateId))) }); const samplesBoundedToFive = Object.values(summary.samplesByCategory).every((samples) => samples.length <= 5); const allHold = summary.total === summary.rootCount + summary.dependencyCount && Object.values(summary.byCategory).reduce((total, count) => total + count, 0) === summary.total && Object.values(summary.byCandidateKind).reduce((total, count) => total + count, 0) === summary.total && samplesBoundedToFive; assert.equal(summary.byCategory.other, 8); assert.equal(summary.samplesByCategory.other.length, 5); assert.equal(samplesBoundedToFive, true); assert.equal(allHold, true) })

test('Planner revalidates bypassed Relation attributes and preserves unrelated safe operations', async () => {
  const groups = [
    group(entity('company', 'Company', 'company')),
    group(entity('industry', 'Industry', 'industry')),
    group(entity('safe', 'Safe Company', 'company')),
    group(relation('bad-relation', 'business_exposure', 'company', 'industry', { financialContribution: { revenueShare: 2 } })),
  ]
  const resolution = await resolve(groups)
  const planned = planKnowledgeChangeSet(plannerInput(groups, resolution.result))
  const operations = planned.changeSet?.knowledgeOperations ?? []
  assert.equal(operations.some((item) => item.type === 'create' && item.object.id.startsWith('relation:')), false)
  assert.equal(operations.filter((item) => item.type === 'create' && item.object.id.startsWith('entity:')).length, 3)
  const review = planned.reviewItems.find((item) => item.candidateId === 'bad-relation')
  assert.equal(review?.origin, 'planner')
  assert.match(review?.rationale ?? '', /Relation attributes are not Schema 0\.3 valid/)
})

