test('InvestmentTheme coverage prompt maps uncertainty to ambiguous_existing', async () => { const { mock } = await resolveTheme(investmentTheme('theme', 'Prompt Theme'), themeExistingAssets([themeAsset('entity:theme', 'Existing Theme')]), { outcome: 'ambiguous_existing', rationale: 'Coverage is uncertain.' }); const request = mock.calls.find((item) => ((item.input as { resolutionCase?: { caseKind?: string } }).resolutionCase?.caseKind) === 'InvestmentThemeCoverageCase'); const instruction = request?.instruction ?? ''; const themeBranch = instruction.split('For other case kinds')[0] ?? ''; assert.match(themeBranch, /coverage is uncertain[\s\S]*ambiguous_existing/i); assert.doesNotMatch(themeBranch, /return uncertain/i); assert.match(instruction, /other case kinds[\s\S]*uncertain/i) })

test('InvestmentTheme coverage vocabulary rejects uncertain while other cases retain it', () => { assert.deepEqual([...semanticOutcomeVocabulary('InvestmentThemeCoverageCase')], ['matches_existing', 'ambiguous_existing', 'potential_new']); assert.ok(!semanticOutcomeVocabulary('InvestmentThemeCoverageCase').includes('uncertain')); assert.ok(semanticOutcomeVocabulary('EntityBindingCase').includes('uncertain')); assert.ok(semanticOutcomeVocabulary('RelationConflictCase').includes('uncertain')); assert.ok(semanticOutcomeVocabulary('ClaimConflictCase').includes('uncertain')); assert.throws(() => validateSemanticResolutionResult({ caseId: 'case', caseKind: 'InvestmentThemeCoverageCase', outcome: 'uncertain', rationale: 'Not legal for Theme coverage.' }, { resolutionCase: { caseId: 'case', caseKind: 'InvestmentThemeCoverageCase', candidateProjection: {}, existingProjections: [], evidence: [], sourceContext: {}, schemaContextSlice: {}, allowedOutcomes: semanticOutcomeVocabulary('InvestmentThemeCoverageCase') }, schemaContext: buildCurationSchemaContext('knowledge_resolution') }), KnowledgeCurationError) })

test('same Company hard identity consolidates names and preserves alternatives as aliases', () => { const consolidated = consolidateExtractions([extractionFixture('unit-a', [entity('a', '中巨芯', 'company', { semanticFields: { ticker: '688549', exchange: 'sh' } })]), extractionFixture('unit-b', [entity('b', '中巨芯科技', 'company', { semanticFields: { ticker: '688549', exchange: 'SH' } })])]); const companies = consolidated.groups.filter((item) => item.kind === 'entity').map((item) => item.candidate as EntityCandidate); assert.equal(companies.length, 1); assert.equal(companies[0]?.name, '中巨芯'); assert.deepEqual(companies[0]?.aliases, ['中巨芯科技']); assert.deepEqual(companies[0]?.semanticFields, { exchange: 'SH', ticker: '688549' }); assert.equal(consolidated.reviewConstraints.length, 0) })

test('unkeyed Company attaches to exactly one matching hard-identity group', () => { const consolidated = consolidateExtractions([extractionFixture('unit-a', [entity('hard', '中巨芯', 'company', { aliases: ['China JG'], semanticFields: { ticker: '688549', exchange: 'SH' } })]), extractionFixture('unit-b', [entity('unkeyed', 'China JG')])]); const companies = consolidated.groups.filter((item) => item.kind === 'entity').map((item) => item.candidate as EntityCandidate); assert.equal(companies.length, 1); assert.deepEqual(companies[0]?.aliases, ['China JG']); assert.equal(consolidated.reviewConstraints.length, 0) })

test('unkeyed Company matching multiple hard identities becomes blocking Review', async () => { const consolidated = consolidateExtractions([extractionFixture('unit-a', [entity('a', 'ABC', 'company', { semanticFields: { ticker: '600001', exchange: 'SH' } })]), extractionFixture('unit-b', [entity('b', 'ABC', 'company', { semanticFields: { ticker: '300001', exchange: 'SZ' } })]), extractionFixture('unit-c', [entity('c', 'ABC')])]); const companies = consolidated.groups.filter((item) => item.kind === 'entity').map((item) => item.candidate as EntityCandidate); assert.equal(companies.length, 3); const review = consolidated.reviewConstraints.find((item) => item.reason.includes('ambiguously matches multiple hard-identity groups')); assert.equal(review?.blocking, true); const { result } = await resolve(consolidated.groups, emptyAssets(), undefined, { consolidationReviews: consolidated.reviewConstraints }); assert.equal(result.intents.find((item) => item.candidateRef === review?.candidateId)?.disposition, 'review') })

test('Company display variants converge Relation and Claim local references', () => { const companyA = entity('company-a', '中巨芯'); const companyB = entity('company-b', '中巨芯（688549.SH）'); const p1 = entity('product-a', 'Product A', 'product'); const p2 = entity('product-b', 'Product B', 'product'); const r1 = relation('relation-a', 'offers_product', 'company-a', 'product-a'); const r2 = relation('relation-b', 'offers_product', 'company-b', 'product-b'); const c1 = claim('claim-a', '中巨芯 supports Product A', 'company-a'); const c2 = claim('claim-b', '中巨芯 supports Product B', 'company-b'); const consolidated = consolidateExtractions([extractionFixture('unit-a', [companyA, p1], [r1], [c1]), extractionFixture('unit-b', [companyB, p2], [r2], [c2], 'block-2')]); const company = consolidated.groups.find((item) => item.kind === 'entity' && (item.candidate as EntityCandidate).entityType === 'company')?.candidate as EntityCandidate; const relations = consolidated.groups.filter((item) => item.kind === 'relation').map((item) => item.candidate as RelationCandidate); const claims = consolidated.groups.filter((item) => item.kind === 'claim').map((item) => item.candidate as ClaimCandidate); assert.equal(company.name, '中巨芯'); assert.equal(new Set(relations.map((item) => item.source.candidateRef)).size, 1); assert.equal(new Set(claims.map((item) => item.subjectRefs[0]?.candidateRef)).size, 1); assert.equal(relations.every((item) => item.source.candidateRef === company.candidateId), true); assert.equal(claims.every((item) => item.subjectRefs[0]?.candidateRef === company.candidateId), true) })

test('representative Company identity variants consolidate into three document-local groups', () => { const sh = entity('sh', '上海新阳'); const shDisplay = entity('sh-display', '上海新阳（300236.SZ）'); const jg = entity('jg', '中巨芯'); const jgDisplay = entity('jg-display', '中巨芯(688549.SH)'); const honeywell = entity('honeywell', '霍尼韦尔'); const honeywellDisplay = entity('honeywell-display', '霍尼韦尔（Honeywell）'); const consolidated = consolidateExtractions([extractionFixture('unit-1', [sh, jg, honeywell]), extractionFixture('unit-2', [shDisplay, jgDisplay, honeywellDisplay], [], [], 'block-2')]); const companies = consolidated.groups.filter((item) => item.kind === 'entity').map((item) => item.candidate as EntityCandidate); assert.equal(companies.length, 3); const shMerged = companies.find((item) => item.name === '上海新阳'); const jgMerged = companies.find((item) => item.name === '中巨芯'); const honeywellMerged = companies.find((item) => item.name === '霍尼韦尔'); assert.deepEqual(shMerged?.semanticFields, { exchange: 'SZ', ticker: '300236' }); assert.deepEqual(jgMerged?.semanticFields, { exchange: 'SH', ticker: '688549' }); assert.deepEqual(honeywellMerged?.aliases, ['Honeywell']) })
